use crate::Result;use rusqlite::Connection;
pub fn migrate(c:&Connection)->Result<()>{c.execute_batch("PRAGMA journal_mode=WAL; PRAGMA synchronous=NORMAL; CREATE TABLE IF NOT EXISTS notes(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL DEFAULT '',content TEXT NOT NULL DEFAULT '',highlights_json TEXT NOT NULL DEFAULT '[]',list_structure_json TEXT NOT NULL DEFAULT '[]',pinned INTEGER NOT NULL DEFAULT 0 CHECK(pinned IN(0,1)),created_at INTEGER NOT NULL,modified_at INTEGER NOT NULL); CREATE INDEX IF NOT EXISTS idx_notes_modified ON notes(modified_at DESC); CREATE INDEX IF NOT EXISTS idx_notes_pinned ON notes(pinned DESC,modified_at DESC);")?;Ok(())}
